html, body {
  height: 100%;
  height: 100dvh;
  overflow: hidden;
  font-family: -apple-system, BlinkMacSystemFont, "PingFang SC", "Hiragino Sans GB",
    "Helvetica Neue", "Segoe UI", sans-serif;
  background: var(--surface-canvas);
  color: var(--ink);
  /* Prevent iOS rubber-banding on body */
  overscroll-behavior: none;
}

/* React Flow tweaks: lighter grid + softer edges.
   （原先此处还有一条灰色 edge-path 规则，被下方 indigo 边线规则
   同优先级后声明恒覆盖，属死代码，已删。） */
.react-flow__background {
  background: var(--surface-canvas);
}
.react-flow__handle {
  opacity: 0;
  pointer-events: none;
}

/* Smooth re-layout: slide nodes between dagre positions instead of
   snapping. Gated behind .canvas-layout-ready so first-mount nodes
   (which start at origin before measurement) pop into place rather
   than flying in. Edges are SVG paths whose `d` can't transition
   cheaply; they re-route instantly, but the eye tracks the cards. */
.canvas-layout-ready .react-flow__node {
  transition: transform 280ms cubic-bezier(0.2, 0.8, 0.2, 1);
}
@media (prefers-reduced-motion: reduce) {
  .canvas-layout-ready .react-flow__node { transition: none; }
}

/* React Flow's controls in dark mode (zoom +/-, fit, etc) */
.dark .react-flow__controls {
  background: var(--surface);
  border-color: var(--line);
}
.dark .react-flow__controls-button {
  background: var(--surface);
  border-bottom-color: var(--line);
  color: var(--ink);
}
.dark .react-flow__controls-button:hover {
  background: var(--surface-muted);
}
.dark .react-flow__controls-button svg {
  fill: currentColor;
}

/* React Flow disables text selection on nodes by default (to keep dragging smooth).
   Re-enable it inside the response container so users can select text to branch. */
[data-chat-node-id],
[data-chat-node-id] * {
  -webkit-user-select: text !important;
  -moz-user-select: text !important;
  user-select: text !important;
  cursor: text;
}
[data-chat-node-id] pre,
[data-chat-node-id] code {
  cursor: text;
}

/* Markdown body inside chat nodes */
.md-body p { margin: 0.55em 0; line-height: 1.7; }
.md-body ol, .md-body ul { margin: 0.55em 0; padding-left: 1.4em; line-height: 1.75; }
.md-body li { margin: 0.25em 0; }
.md-body strong { color: var(--ink-strong); font-weight: 600; }
/* Tailwind preflight strips link styling — restore it, else links read as
   plain text. Local-file links add decoration-dotted on top (preview hint). */
.md-body a {
  color: var(--accent-ink);
  text-decoration: underline;

