361	      >
362	        <div className="w-7 h-7 rounded-full bg-accent text-ink-inverse text-label flex items-center justify-center mt-0.5 shrink-0 font-medium">
363	          你
364	        </div>
365	        <div
366	          className={`flex-1 text-body text-ink leading-relaxed pt-1 font-medium min-w-0 ${
367	            // Peek pins the whole card to PEEK_CARD_HEIGHT with the body as the
