391	          )}
392	        </div>
393	        {data.isPeeked && (
394	          <button
395	            onClick={(e) => {
396	              e.stopPropagation();
397	              data.onTogglePeek(n.id);
398	            }}
399	            title="收起预览"
400	            aria-label="收起预览"
401	            className="shrink-0 mt-0.5 px-2 h-7 rounded-md bg-surface border border-line-strong text-ink-muted hover:bg-ink hover:text-ink-inverse hover:border-ink active:scale-95 flex items-center gap-1 text-label font-medium transition-colors shadow-raise"
402	          >
403	            <svg
404	              width="13"
405	              height="13"
406	              viewBox="0 0 24 24"
407	              fill="none"
408	              stroke="currentColor"
409	              strokeWidth="2.2"
410	              strokeLinecap="round"
411	              strokeLinejoin="round"
412	              aria-hidden
413	            >
414	              <path d="M18 15l-6-6-6 6" />
415	            </svg>
416	            收起
417	          </button>
418	        )}
419	        <button
420	          onClick={goRead}
421	          title="线性阅读"
422	          aria-label="线性阅读"
423	          className="shrink-0 mt-0.5 px-2 h-7 rounded-md bg-surface border border-line-strong text-ink-muted hover:bg-ink hover:text-ink-inverse hover:border-ink active:scale-95 flex items-center gap-1 text-label font-medium transition-colors shadow-raise"
424	        >
425	          <svg
426	            width="13"
427	            height="13"
428	            viewBox="0 0 24 24"
429	            fill="none"
430	            stroke="currentColor"
431	            strokeWidth="2.2"
432	            strokeLinecap="round"
433	            strokeLinejoin="round"
434	          >
435	            <path d="M15 3h6v6M9 21H3v-6M21 3l-7 7M3 21l7-7" />
436	          </svg>
437	          阅读
438	        </button>
439	      </div>
440	
441	      <div
442	        ref={bodyRef}
443	        data-chat-node-id={n.id}
444	        onClick={onMarkClick}
445	        className={`px-5 py-4 md-body text-body text-ink-muted overflow-y-auto nodrag nowheel nopan ${
446	          data.isPeeked ? "flex-1 min-h-0" : "max-h-[420px]"
447	        }`}
448	      >
449	        {isStreaming ? (
450	          <>
451	            <div
452	              ref={thinkingRef}
453	              style={{ display: "none" }}
454	              className="items-center gap-1.5 mb-1 text-ui text-ink-faint"
455	            >
456	              <span className="w-1.5 h-1.5 rounded-full bg-accent animate-pulse" />
457	              思考中…
458	            </div>
459	            <div
460	              ref={streamRef}
461	              className="whitespace-pre-wrap break-words leading-relaxed"
462	            />
463	            <span className="streaming-cursor" />
464	          </>
465	        ) : n.response ? (
466	          <ReactMarkdown
467	            remarkPlugins={REMARK_PLUGINS}
468	            rehypePlugins={REHYPE_FULL}
469	            components={MD_COMPONENTS}
470	            urlTransform={MD_URL_TRANSFORM}
471	          >
472	            {n.response}
473	          </ReactMarkdown>
474	        ) : (
475	          <EmptyResponseNotice hasToolCalls={(n.toolCalls?.length ?? 0) > 0} />
476	        )}
477	        {errorSuperseded && (
478	          <SupersededErrorNotice nodeId={n.id} errorMessage={n.errorMessage} />
479	        )}
480	        {isError &&
481	          !errorSuperseded &&
482	          (n.errorMessage === "aborted" ? (
483	            <div className="mt-3 p-2 bg-surface-muted border border-line rounded text-ink-muted text-xs flex items-start gap-2">
484	              <div className="flex-1">已停止生成</div>
485	              <button
486	                onClick={(e) => {
487	                  e.stopPropagation();
488	                  retryNode(n.id);
489	                }}
490	                className="shrink-0 px-2 py-0.5 rounded bg-accent text-ink-inverse text-label hover:bg-accent-strong active:scale-95 transition-transform"
491	              >
492	                ↻ 重新发送
493	              </button>
494	            </div>
495	          ) : (
496	            <div className="mt-3 p-2 bg-danger-muted border border-danger-line rounded text-danger-ink text-xs flex items-start gap-2">
497	              <div className="flex-1">出错：{n.errorMessage}</div>
498	              <button
499	                onClick={(e) => {
500	                  e.stopPropagation();
501	                  retryNode(n.id);
502	                }}
503	                className="shrink-0 px-2 py-0.5 rounded bg-danger text-ink-inverse text-label hover:bg-danger-strong active:scale-95 transition-transform"
504	              >
505	                ↻ 重新生成
506	              </button>
507	            </div>
508	          ))}
509	      </div>
510	
511	      <NodeFooter node={n} isStreaming={isStreaming} />
512	
513	      <Handle type="source" position={Position.Bottom} />
514	    </div>
515	  );
516	}
517	
518	// React.memo with custom comparison so streaming a single node doesn't
519	// re-render every other node on every token. Hot path: handleStreamEvent
520	// in sessionStore preserves identity for non-streaming nodes (only the
521	// streaming node's object is replaced), so `prev.node === next.node`
522	// catches them. childAnchors is rebuilt by the Canvas selector on every
523	// nodeMap change but is small per-parent — value-compare it.
524	export const ChatNode = memo(ChatNodeImpl, (prev, next) => {
525	  if (prev.data.node !== next.data.node) return false;
526	  if (prev.data.isActive !== next.data.isActive) return false;
527	  if (prev.data.collapsed !== next.data.collapsed) return false;
528	  if (prev.data.isPeeked !== next.data.isPeeked) return false;
529	  if (prev.data.descendantCount !== next.data.descendantCount) return false;
530	  const a = prev.data.childAnchors;
531	  const b = next.data.childAnchors;
532	  if (a !== b) {
533	    if (a.length !== b.length) return false;
534	    for (let i = 0; i < a.length; i++) {
535	      if (a[i].childId !== b[i].childId || a[i].text !== b[i].text) return false;
536	    }
537	  }
538	  return true;
539	});
540	
541	function NodeFooter({
542	  node,
543	  isStreaming,
544	}: {
545	  node: ChatNodeData;
546	  isStreaming: boolean;
547	}) {
548	  const [open, setOpen] = useState(false);
549	  const abortStream = useSessionStore((s) => s.abortStream);
550	
551	  if (open) {
552	    return <FollowupInput node={node} onClose={() => setOpen(false)} />;
553	  }
554	
555	  return (
556	    <div className="px-5 py-2 border-t border-line-faint flex items-center gap-2 text-xs text-ink-muted">
557	      {isStreaming ? (
558	        <>
559	          <span className="w-1.5 h-1.5 bg-positive rounded-full animate-pulse" />
560	          <span>正在生成…</span>
561	          <button
562	            onClick={(e) => {
563	              e.stopPropagation();
564	              abortStream(node.id);
565	            }}
566	            className="ml-2 px-2 py-0.5 rounded border border-line-strong bg-surface text-ink-muted hover:bg-ink hover:text-ink-inverse hover:border-ink active:scale-95 transition-colors flex items-center gap-1"
567	            title="停止生成 (Esc)"
568	            aria-label="停止生成"
569	          >
570	            <span className="inline-block w-2 h-2 bg-current rounded-[1px]" />
571	            停止
572	          </button>
573	        </>
574	      ) : (
575	        <>
576	          <ToolCallBadge toolCalls={node.toolCalls} />
577	          <TokenMeta tokenCount={node.tokenCount} variant="full" />
578	          {node.response && (
579	            <CopyButton
580	              text={node.response}
581	              className="nodrag ml-2 px-2 py-0.5 rounded text-ink-muted hover:bg-surface-muted hover:text-ink-strong transition-colors"
582	            />
583	          )}
584	          <button
585	            onClick={() => setOpen(true)}
586	            className="ml-1 px-2 py-0.5 rounded text-ink-muted hover:bg-surface-muted hover:text-ink-strong transition-colors"
587	          >
588	            + 追问
589	          </button>
590	        </>
591	      )}
592	      <span className="ml-auto text-ink-faint italic text-label">
593	        或选中文字 → ⌘K 提问
594	      </span>
595	    </div>
596	  );
597	}
598	
599	function FollowupInput({
600	  node,
601	  onClose,
602	}: {
603	  node: ChatNodeData;
604	  onClose: () => void;
605	}) {
606	  const [q, setQ] = useState("");
607	  const [zoneOpen, setZoneOpen] = useState(false);
608	  const ref = useRef<HTMLTextAreaElement>(null);
609	  const streamBranch = useSessionStore((s) => s.streamBranch);
610	  const sendKey = useSessionStore((s) => s.sendKey);
611	  const sessionMode = useSessionStore((s) => s.session?.mode);
612	  const chatEnhanced = useSessionStore((s) => s.chatEnhanced);
613	  const setChatEnhanced = useSessionStore((s) => s.setChatEnhanced);
614	  // Skills show in every mode; picking one in pure chat auto-enables 增强模式
615	  // (per-turn spawn flag — Header badge reflects it) so the skill can run.
616	  const matchedSkills = useSkillSuggestions(q, true);
617	  const pickSkill = (name: string) => {
618	    if (sessionMode === "chat" && !chatEnhanced) setChatEnhanced(true);
619	    setQ(`/${name} `);
620	    ref.current?.focus();
621	  };
622	  const slashNav = useSlashNav(matchedSkills.length, q, (i) =>
623	    pickSkill(matchedSkills[i].name),
624	  );
625	
626	  useEffect(() => {
627	    ref.current?.focus();
628	  }, []);
629	
630	  const submit = async () => {
631	    const text = q.trim();
632	    if (!text) return;
633	    onClose();
634	    streamBranch(node.id, text, null);
635	  };
636	
637	  return (
638	    <div className="relative border-t border-line-faint bg-surface-canvas/60">
639	      <SkillPickerList
640	        skills={matchedSkills}
641	        onPick={pickSkill}
642	        activeIndex={slashNav.active}
643	      />
644	      {/* px-1.5 insets the full-width textarea so its :focus-visible outline
645	          (globals.css — 2px solid + 2px offset, a non-layered rule utilities
646	          can't override) stays inside the card border instead of poking past
647	          it. */}
648	      <div className="px-1.5">
649	        <textarea
650	          ref={ref}
651	          value={q}
652	          onChange={(e) => setQ(e.target.value)}
653	          onKeyDown={(e) => {
654	            if (slashNav.handleKeyDown(e)) return;
655	            if (isSendCombo(e, sendKey)) {
656	              e.preventDefault();
657	              submit();
658	            } else if (e.key === "Escape") {
659	              e.preventDefault();
660	              onClose();
661	            }
662	          }}
663	          placeholder={`对整段回复继续追问…（${sendHint(sendKey)}）`}
664	          rows={2}
665	          className="w-full px-3.5 py-3 outline-none resize-none text-sm bg-transparent text-ink placeholder:text-ink-faint"
666	        />
667	      </div>
668	      <div className="px-3 py-1.5 flex items-center justify-end gap-2 text-xs">
669	        <button
670	          onClick={() => setZoneOpen(true)}
671	          title="专注写作模式（全屏 Markdown 编辑 + 预览）"
672	          className="mr-auto px-2 py-0.5 text-ink-muted hover:text-ink-strong inline-flex items-center gap-1"
673	        >
674	          <span aria-hidden>⛶</span>
675	          <span>专注写作</span>
676	        </button>
677	        <button
678	          onClick={onClose}
679	          className="px-2 py-0.5 text-ink-muted hover:text-ink-strong"
680	        >
681	          取消
682	        </button>
683	        <button
684	          onClick={submit}
685	          disabled={!q.trim()}
686	          className="px-2.5 py-0.5 rounded bg-accent text-ink-inverse disabled:opacity-40 hover:bg-accent-strong"
687	        >
688	          提问
689	        </button>
690	      </div>
691	      {zoneOpen && (
692	        <ZoneEditor
693	          value={q}
694	          onChange={setQ}
695	          onSubmit={() => {
696	            if (!q.trim()) return;
697	            setZoneOpen(false);
698	            submit();
699	          }}
700	          onClose={() => setZoneOpen(false)}
701	          title="继续追问"
702	          placeholder="专注写下你的追问，支持 Markdown……"
703	          submitLabel="提问"
704	          submitDisabled={!q.trim()}
705	        />
706	      )}
707	    </div>
708	  );
709	}
710	
711	function truncate(s: string, n: number) {
712	  return s.length > n ? s.slice(0, n) + "…" : s;
713	}
714	
715	// Inline token meter shared by the compact-card right side and the
716	// Stage 17: small badge that surfaces tool-call count on the canvas
717	// card + fullscreen footer. Hidden when count is 0 so chat-mode nodes
718	// (which rarely invoke tools) don't grow extra clutter. Click is
719	// non-interactive — drill-down lives in the timeline inside the
720	// fullscreen view.
721	//
722	// 🔧 is every call in the turn; delegation gets its own 🤖 / ⚙ count so a turn
723	// that fanned out reads as such at a glance instead of just showing an
724	// inflated tool number.
725	function ToolCallBadge({ toolCalls }: { toolCalls: ToolCall[] }) {
726	  const tree = buildToolTree(toolCalls);
727	  const counts = countToolTree(tree);
728	  if (counts.total === 0) return null;
729	  const labels = walkToolTree(tree)
730	    .filter((n) => n.kind === "subagent")
731	    .map((n) => subagentLabel(n.meta));
732	  return (
733	    <span className="shrink-0 inline-flex items-center gap-1 text-nano tabular-nums text-ink-muted">
734	      <span title={`本轮共 ${counts.total} 次工具调用`}>🔧{counts.total}</span>
735	      {counts.subagents > 0 && (
736	        <span title={`派了 ${counts.subagents} 个子 Agent：${labels.join("、")}`}>
737	          🤖{counts.subagents}
738	        </span>
739	      )}
740	      {counts.workflows > 0 && (
741	        <span title={`跑了 ${counts.workflows} 个 Workflow`}>
742	          ⚙{counts.workflows}
743	        </span>
744	      )}
745	    </span>
746	  );
747	}
748	
749	// fullscreen footer. Three buckets (↑ in, ↓ out, ⚡ cache hit). cache
750	// creation is collapsed into the cache slot only when non-zero (rare —
751	// happens on first cli-multi turn) by appending +N. We deliberately
752	// omit fields that are zero to keep idle nodes uncluttered.
753	function TokenMeta({
754	  tokenCount,
755	  variant,
756	}: {
757	  tokenCount: ChatNodeData["tokenCount"];
758	  variant: "compact" | "full";
759	}) {
760	  const { input, output, cacheRead, cacheCreation } = tokenCount;
761	  const hasAny =
762	    input > 0 || output > 0 || cacheRead > 0 || cacheCreation > 0;
763	  if (!hasAny) {
764	    return (
765	      <span
766	        className={
767	          variant === "compact"
768	            ? "shrink-0 text-nano text-ink-faint tabular-nums"
769	            : "text-ink-faint tabular-nums"
770	        }
771	      >
772	        —
773	      </span>
774	    );
775	  }
776	  const baseCls = "tabular-nums whitespace-nowrap";
777	  const sizeCls = variant === "compact" ? "text-nano" : "text-label";
778	  return (
779	    <span
780	      className={`shrink-0 inline-flex items-center gap-1.5 ${sizeCls} ${baseCls} text-ink-muted`}
781	      title={`输入 ${input} · 输出 ${output} · 缓存命中 ${cacheRead}${
782	        cacheCreation > 0 ? ` · 缓存写入 ${cacheCreation}` : ""
783	      }`}
784	    >
785	      <span>↑{formatTokens(input)}</span>
786	      <span>↓{formatTokens(output)}</span>
787	      {(cacheRead > 0 || cacheCreation > 0) && (
788	        <span className="text-positive">
789	          ⚡{formatTokens(cacheRead)}
790	          {cacheCreation > 0 ? `+${formatTokens(cacheCreation)}` : ""}
791	        </span>
792	      )}
793	    </span>
794	  );
795	}
796	
