          aria-hidden
          title={n.status === "done" ? (isUnread ? "未读" : "已读") : undefined}
        />
        <div className="px-4 py-3 flex items-center gap-2.5">
          {indexLabel && (
            <span className="shrink-0 text-label font-mono text-ink-faint tabular-nums">
              {indexLabel}
