          <div className="flex-1 min-w-0">
            <div className="text-title font-semibold text-ink-strong leading-tight truncate">
              {labelText}
            </div>
            {n.parentAnchor && (
              <div className="mt-0.5 text-label text-fork-ink truncate">
                ↳ {truncate(n.parentAnchor.selectedText, 22)}
