1	// trellis 的大门（S1 P1'，progress/project-workspace-layer.md）。
2	//
3	// 为什么不是直接 `next start`：终端必须是这个平台的一个**接口**——同一个域名、
4	// 同一个端口、同一个 cookie 闸，本机和远程走完全相同的 URL。而终端是 WebSocket，
5	// Next 的 App Router 不能升级 WS，bun 的 node:http upgrade socket 又写不回客户端
6	// （两条都实测过，见 progress 的 Verified Facts）。唯一能同时满足「同源」和
7	// 「WS 可用」的位置，就是在 Next 前面放一个 Bun.serve —— 它的原生 WebSocket 是好的。
8	//
9	//   :PORT  server.ts (Bun.serve)
10	//      ├─ /term/*  → ttyd 127.0.0.1:<ttydPort>   （HTTP + WS，先校 cookie）
11	//      └─ /*       → next start 127.0.0.1:<nextPort>
12	//
13	// 三条承重属性都已实测：WS upgrade 通、**SSE 逐条增量到达**（~4ms 开销，没被
14	// 缓冲——trellis 整个对话是 SSE，缓冲了就全瘫）、POST 请求体透传。
15	//
16	// 部署面刻意零改动：launchd plist 调的是 `bun --bun run start -- -p 3088`，
17	// 我们只把 package.json 的 start 指到本文件，并在这里认 `-p`。
18	
19	import { spawn, type Subprocess } from "bun";
20	import { AUTH_COOKIE } from "./lib/auth-cookie";
21	import { hasTtyd, TTYD_HOST_DEPENDENCY_NOTE } from "./lib/ttyd-dependency";
22	import {
23	  deployPaths,
24	  isDeployStateFresh,
25	  readDeployState,
26	  readReleaseInfo,
27	  tailLog,
28	} from "./lib/deploy-state";
29	
30	const argv = process.argv.slice(2);
31	const pIdx = argv.findIndex((a) => a === "-p" || a === "--port");
32	const PORT =
33	  Number(pIdx >= 0 ? argv[pIdx + 1] : undefined) ||
34	  Number(process.env.PORT) ||
35	  3088;
36	
37	// Next 挪到一个只监听 127.0.0.1 的内部端口 —— 外面只应该看得见大门。
38	const NEXT_PORT = Number(process.env.TRELLIS_NEXT_PORT) || PORT + 99;
39	const NEXT_UP = `http://127.0.0.1:${NEXT_PORT}`;
40	
41	if (!hasTtyd()) {
42	  console.warn(`[trellis] ${TTYD_HOST_DEPENDENCY_NOTE}`);
43	}
44	
45	// 转发给上游时**必须换掉 Host**（S79 花了很久才钉死的一个坑）。
46	//
47	// 症状：从开发 shell 里起的实例，`/` 和 `/login` 全部超时无响应，而直接打
48	// 内部 Next 端口一切正常；大门自己的 /__gate/health 也正常。日志显示一次
49	// curl 打进来会触发**几百次** fetch handler 调用，user-agent 全是 curl。
50	//
51	// 机制：环境里存在 http_proxy 时（本机 clash 会塞 127.0.0.1:7897），bun 的
52	// fetch 按**请求头里的 Host** 而不是 URL 的 authority 去决定连谁 —— 于是
53	// `Host: 127.0.0.1:3088` 让大门把请求发回了自己，自我循环直到超时。实测隔离
54	// 到单个请求头：只带 host → 超时，去掉 host 的全套真实请求头 → 200。
55	//
56	// prod 至今没炸只是因为 launchd 不继承 shell 环境（没有 http_proxy）——
57	// 换句话说这是个**潜伏的坑**，不是本次改动引入的（HEAD~1 的大门实测同样中招）。
58	// 进程内 delete process.env.http_proxy 没用，bun 在用户代码跑之前就把代理
59	// 配置定死了。所以修在请求头这一侧，顺带也是反向代理本来就该有的行为。
60	//
61	// 原始 Host 走 x-forwarded-host 传下去，别让 Next 丢掉「用户是从哪个域名来的」
62	// —— 公网隧道下 /login 的重定向要靠它拼绝对地址（见 proxy.ts）。
63	function upstreamHeaders(h: Headers, upstreamHost: string): Headers {
64	  const out = new Headers(h);
65	  const original = h.get("host");
66	  if (original && !h.has("x-forwarded-host")) {
67	    out.set("x-forwarded-host", original);
68	  }
69	  out.set("host", upstreamHost);
70	  return out;
71	}
72	
73	// 与 proxy.ts 同一套判据：两个变量任一缺失 = 闸关（本地开发免摩擦）。
74	// /term 不走 Next，所以 proxy.ts 那个 middleware 管不到它，闸得在这里自己把。
75	const PASS = process.env.TRELLIS_AUTH_PASS;
76	const TOKEN = process.env.TRELLIS_AUTH_TOKEN;
77	const gateOn = Boolean(PASS && TOKEN);
78	
79	function authed(req: Request): boolean {
80	  if (!gateOn) return true;
81	  const raw = req.headers.get("cookie") ?? "";
82	  for (const part of raw.split(";")) {
83	    const [k, ...v] = part.trim().split("=");
84	    if (k === AUTH_COOKIE) return v.join("=") === TOKEN;
85	  }
86	  return false;
87	}
88	
89	// ── Next 子进程 ────────────────────────────────────────────────────────────
90	//
91	// 大门比 Next 活得久（S79）。原本 Next 一挂大门就 `process.exit(1)`，靠
92	// launchd 的 KeepAlive 拉起来 —— 而 plist 没有 ThrottleInterval，坏版本会被
93	// 无限 respawn，浏览器侧只剩 connection refused，看不到任何原因。现在改成：
94	// 大门先占住端口，Next 自己带退避重启，起不来就出维护页说人话。
95	let nextProc: Subprocess | null = null;
96	let nextReady = false;
97	let consecutiveFailures = 0;
98	let lastExitCode: number | null = null;
99	let shuttingDown = false;
100	
101	// 一次性口令，只下发给自己 spawn 的 Next —— 排空钩子
102	// （app/api/internal/shutdown）靠它认人。
103	const SHUTDOWN_TOKEN = crypto.randomUUID();
104	
105	async function portOpen(port: number): Promise<boolean> {
106	  try {
107	    const sock = await Bun.connect({
108	      hostname: "127.0.0.1",
109	      port,
110	      socket: { data() {} },
111	    });
112	    sock.end();
113	    return true;
114	  } catch {
115	    return false;
116	  }
117	}
118	
119	async function waitFor(port: number, timeoutMs: number): Promise<boolean> {
120	  const deadline = Date.now() + timeoutMs;
121	  while (Date.now() < deadline) {
122	    if (await portOpen(port)) return true;
123	    await Bun.sleep(200);
124	  }
125	  return false;
126	}
127	
128	/** spawn 一次 Next 并等它监听。返回是否起来了。 */
129	async function bootNext(): Promise<boolean> {
130	  nextProc = spawn({
131	    cmd: ["bun", "--bun", "node_modules/.bin/next", "start", "-p", String(NEXT_PORT), "-H", "127.0.0.1"],
132	    env: {
133	      ...process.env,
134	      PORT: String(NEXT_PORT),
135	      TRELLIS_SHUTDOWN_TOKEN: SHUTDOWN_TOKEN,
136	    },
137	    stdout: "inherit",
138	    stderr: "inherit",
139	  });
140	  // 和「子进程直接退出」赛跑。只等端口的话，启动即崩的 Next（比如 .next 不存在）
141	  // 也要干等满 60s 才被判失败 —— 那 60s 里维护页会一直说「正在启动」，退避重启
142	  // 也压根没开始。实测这种崩溃 1s 内就退出了。
143	  const proc = nextProc;
144	  const listened = await Promise.race([
145	    waitFor(NEXT_PORT, 60_000),
146	    proc.exited.then(() => false),
147	  ]);
148	  if (listened) return true;
149	  lastExitCode = proc.exitCode;
150	  console.error(
151	    proc.exitCode !== null
152	      ? `[trellis] next exited during startup (code=${proc.exitCode})`
153	      : `[trellis] next did not listen on ${NEXT_PORT} within 60s`,
154	  );
155	  try {
156	    proc.kill();
157	  } catch {
158	    /* 已经没了 */
159	  }
160	  return false;
161	}
162	
163	// 起不来就退避重试，永不放弃 —— launchd 重启一遍也是同样的结果，还会把大门
164	// 一起带走（连维护页都没了）。指数退避封顶 30s。
165	async function superviseNext(): Promise<void> {
166	  let backoff = 1000;
167	  while (!shuttingDown) {
168	    const startedAt = Date.now();
169	    if (await bootNext()) {
170	      nextReady = true;
171	      consecutiveFailures = 0;
172	      // 新的 Next = ttyd 可能落在别的端口上，作废缓存（见 resolveTtydPort）。
173	      ttydPort = null;
174	      console.log(`[trellis] next ready on 127.0.0.1:${NEXT_PORT}`);
175	      await nextProc!.exited;
176	      nextReady = false;
177	      if (shuttingDown) return;
178	      lastExitCode = nextProc?.exitCode ?? null;
179	      console.error(`[trellis] next exited (code=${lastExitCode}) — restarting`);
180	      // 之前活够久 = 偶发崩溃，别背着上一轮的退避惩罚。
181	      if (Date.now() - startedAt > 60_000) backoff = 1000;
182	    } else {
183	      consecutiveFailures++;
184	    }
185	    if (shuttingDown) return;
186	    await Bun.sleep(backoff);
187	    backoff = Math.min(30_000, backoff * 2);
188	  }
189	}
190	
191	// 优雅停机：先让 Next 排空（abort 在跑的 run、收走 ttyd），再 kill。
192	// 不排空的话，spawn 出去的 claude/codex 会 reparent 到 launchd 继续跑、继续
193	// 写 jsonl、继续烧 token，DB 里那行还卡在 streaming。
194	async function shutdown(): Promise<void> {
195	  if (shuttingDown) return;
196	  shuttingDown = true;
197	  if (nextReady) {
198	    try {
199	      await fetch(`${NEXT_UP}/api/internal/shutdown`, {
200	        method: "POST",
201	        headers: {
202	          "x-trellis-shutdown": SHUTDOWN_TOKEN,
203	          // 这条路由同样盖在 proxy.ts 的 cookie 闸下面。大门手里就有 TOKEN。
204	          ...(gateOn ? { cookie: `${AUTH_COOKIE}=${TOKEN}` } : {}),
205	        },
206	        signal: AbortSignal.timeout(10_000),
207	      });
208	    } catch {
209	      /* 排空是尽力而为，超时/失败照样往下走 kill */
210	    }
211	  }
212	  try {
213	    nextProc?.kill();
214	  } catch {
215	    /* 已经没了 */
216	  }
217	  await Promise.race([
218	    nextProc?.exited ?? Promise.resolve(0),
219	    Bun.sleep(3000),
220	  ]);
221	  process.exit(0);
222	}
223	
224	for (const sig of ["SIGINT", "SIGTERM"] as const) {
225	  process.on(sig, () => {
226	    void shutdown();
227	  });
228	}
229	
230	// ── ttyd 端口发现 ──────────────────────────────────────────────────────────
231	// ttyd 的生命周期归 lib/server/ttyd.ts（跑在 Next 进程里，懒启动）。大门这边
232	// 只需要知道它监听在哪 —— 通过 Next 的内部接口问一次，缓存住；ttyd 重启换端口
233	// 时下一次 /term 请求会重新问。
234	let ttydPort: number | null = null;
235	async function resolveTtydPort(cookie: string): Promise<number | null> {
236	  if (ttydPort && (await portOpen(ttydPort))) return ttydPort;
237	  try {
238	    // 带上调用方那份 cookie —— 那条内部接口同样盖在 proxy.ts 的闸下面，
239	    // 而我们在调这里之前已经 authed(req) 过了。这样闸上不用开任何
240	    // 「内部 header 免验」的口子（那种口子外部可以伪造）。
241	    const r = await fetch(`${NEXT_UP}/api/terminals/port`, {
242	      headers: cookie ? { cookie } : {},
243	    });
244	    if (!r.ok) return null;
245	    const d = (await r.json()) as { port: number | null };
246	    ttydPort = d.port ?? null;
247	  } catch {
248	    ttydPort = null;
249	  }
250	  return ttydPort;
251	}
252	
253	// bun 的 fetch **会自动解压**上游响应（而且它自己会加 Accept-Encoding，
254	// 所以哪怕客户端没要压缩、上游也可能返回 gzip）。若把原样的响应头贴回去，
255	// 客户端拿到的就是「声称是 gzip 的明文」+ 一个对不上的 Content-Length ——
256	// curl 默认不解压所以看着没事，**浏览器当场卡死**（这个 bug 差点上 prod）。
257	// 这三个描述传输编码的头必须由我们这层重新生成，不能透传。
258	function passthroughHeaders(h: Headers): Headers {
259	  const out = new Headers(h);
260	  out.delete("content-encoding");
261	  out.delete("content-length");
262	  out.delete("transfer-encoding");
263	  return out;
264	}
265	
266	// ── 维护页 ─────────────────────────────────────────────────────────────────
267	// Next 没就绪时的门面。要点：**未认证的访客只看得到「正在更新」**，sha /
268	// 日志 / 路径只在带着有效 cookie 时才渲染 —— 这台机器挂着公网隧道，stderr
269	// 里什么都有。
270	function esc(s: string): string {
271	  return s.replace(/[&<>]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;" })[c]!);
272	}
273	
274	function nextStatus(): "ready" | "starting" | "down" {
275	  if (nextReady) return "ready";
276	  return consecutiveFailures > 0 ? "down" : "starting";
277	}
278	
279	function maintenancePage(detailed: boolean): Response {
280	  const st = readDeployState();
281	  const status = nextStatus();
282	  // 只有「正在进行中的部署」才有资格解释当前的不可用。判据提到 deploy-state.ts
283	  // 共享 —— 设置页的「能不能再发一次更新」问的是同一个问题，两处不能各判各的。
284	  const fresh = isDeployStateFresh(st);
285	  const headline =
286	    fresh && st.phase !== "done" && st.phase !== "idle"
287	      ? { preflight: "正在检查", stage: "正在准备新版本", install: "正在安装依赖", build: "正在构建", smoke: "正在预检新版本", backup: "正在备份数据库", switch: "正在切换版本", verify: "正在验活", rollback: "正在回滚", failed: "本次更新失败", broken: "更新失败且回滚未成功", done: "", idle: "" }[st.phase] ?? "正在更新"
288	      : status === "down"
289	        ? "服务启动失败"
290	        : "服务正在启动";
291	
292	  const detail = detailed
293	    ? `
294	    <dl>
295	      <dt>网关</dt><dd>up · :${PORT}</dd>
296	      <dt>Next</dt><dd>${status}${consecutiveFailures ? ` · 连续失败 ${consecutiveFailures} 次` : ""}${lastExitCode !== null ? ` · 上次退出码 ${lastExitCode}` : ""}</dd>
297	      ${st ? `<dt>部署阶段</dt><dd>${esc(st.phase)} · ${esc(st.message)}</dd>` : ""}
298	      ${st?.sha ? `<dt>目标版本</dt><dd><code>${esc(st.sha)}</code></dd>` : ""}
299	      ${st?.previousSha ? `<dt>回滚目标</dt><dd><code>${esc(st.previousSha)}</code></dd>` : ""}
300	    </dl>
301	    <p class="hint">回滚命令：<code>${esc(deployPaths().bin)}/rollback.sh</code></p>
302	    ${(() => {
303	      const t = tailLog(st?.logFile ?? null);
304	      return t ? `<pre>${esc(t)}</pre>` : "";
305	    })()}`
306	    : `<p class="hint">服务恢复后本页会自动刷新。</p>`;
307	
308	  return new Response(
309	    `<!doctype html><html lang="zh"><head><meta charset="utf-8">
310	<meta name="viewport" content="width=device-width,initial-scale=1">
311	<title>trellis · ${esc(headline)}</title>
312	<meta http-equiv="refresh" content="5">
313	<style>
314	:root{color-scheme:dark light}
315	body{margin:0;min-height:100vh;display:grid;place-items:center;background:#0f1115;color:#e6e8ec;
316	     font:15px/1.6 ui-sans-serif,-apple-system,"PingFang SC",system-ui,sans-serif}
317	main{max-width:760px;padding:32px}
318	h1{font-size:20px;margin:0 0 4px}
319	.sub{color:#8b93a1;margin:0 0 20px}
320	dl{display:grid;grid-template-columns:max-content 1fr;gap:4px 16px;margin:0 0 16px}
321	dt{color:#8b93a1}
322	code{font:13px ui-monospace,SFMono-Regular,Menlo,monospace}
323	pre{background:#161a21;border:1px solid #232936;border-radius:8px;padding:12px;overflow:auto;
324	    max-height:320px;font:12px/1.5 ui-monospace,SFMono-Regular,Menlo,monospace;color:#c3cad6}
325	.hint{color:#8b93a1;font-size:13px}
326	.dot{display:inline-block;width:8px;height:8px;border-radius:50%;background:#e0a03a;margin-right:8px;
327	     animation:p 1.4s ease-in-out infinite}
328	@keyframes p{50%{opacity:.25}}
329	</style></head><body><main>
330	<h1><span class="dot"></span>${esc(headline)}</h1>
331	<p class="sub">trellis 暂时不可用，网关还在。</p>
332	${detail}
333	</main></body></html>`,
334	    {
335	      status: 503,
336	      headers: {
337	        "content-type": "text/html; charset=utf-8",
338	        "retry-after": "5",
339	        "cache-control": "no-store",
340	      },
341	    },
342	  );
343	}
344	
345	// ── 大门 ───────────────────────────────────────────────────────────────────
346	// 注意顺序：**先占端口再拉 Next**。反过来的话，Next 起不来的那 60s 里外面
347	// 连的是一个不存在的端口（connection refused），维护页根本没机会出现。
348	void superviseNext();
349	
350	// 每条 WS 连接随身带的上下文：目标 ttyd 端口 / 路径，以及上游连接与
351	// 「上游还没连上时」的待发队列。
352	type TermSocket = {
353	  port: number;
354	  path: string;
355	  search: string;
356	  up?: WebSocket;
357	  q: (string | Uint8Array)[];
358	};
359	
360	Bun.serve<TermSocket>({
361	  port: PORT,
362	  // SSE / 长连接不能被空闲超时掐死。trellis 的一轮生成可以几分钟不吐字节
363	  // （思考期），默认 idleTimeout 会当场断流。
364	  idleTimeout: 0,
365	  async fetch(req, server) {
366	    const url = new URL(req.url);
367	
368	    // 网关自己的健康面。**不经 Next**，所以 Next 挂着的时候它照样准确 ——
369	    // 部署脚本的 verify 和 daily-health 都指望这一条。粗粒度状态对谁都公开
370	    // （它就是「服务活没活」，不含任何内部信息），版本详情要认证。
371	    if (url.pathname === "/__gate/health") {
372	      const body: Record<string, unknown> = {
373	        gate: "up",
374	        next: nextStatus(),
375	        consecutiveFailures,
376	        // 认证闸开没开。不是秘密（一个 401 就暴露了），但部署流水线要靠它做
377	        // 「切换前后闸状态不许 on→off」的断言 —— 凭证来自 .env.local 这类
378	        // 未跟踪文件，一旦没被带进 release，闸会静默关掉。
379	        auth: gateOn ? "on" : "off",
380	      };
381	      if (authed(req)) {
382	        const st = readDeployState();
383	        body.deploy = st ? { phase: st.phase, sha: st.sha } : null;
384	        body.release = readReleaseInfo(deployPaths().current);
385	        body.lastExitCode = lastExitCode;
386	      }
387	      return Response.json(body, {
388	        headers: { "cache-control": "no-store" },
389	      });
390	    }
391	
392	    if (url.pathname === "/term" || url.pathname.startsWith("/term/")) {
393	      if (!authed(req)) return new Response("Unauthorized", { status: 401 });
394	      // /term 的端口发现要问 Next，Next 不在就没得问。
395	      if (!nextReady) return maintenancePage(authed(req));
396	      const port = await resolveTtydPort(req.headers.get("cookie") ?? "");
397	      if (!port) {
398	        return new Response("终端未就绪（ttyd 未启动）", { status: 503 });
399	      }
400	      // ttyd 挂在自己的根路径下，把 /term 前缀剥掉再转发。
401	      const path = url.pathname.replace(/^\/term/, "") || "/";
402	
403	      if (req.headers.get("upgrade")?.toLowerCase() === "websocket") {
404	        if (server.upgrade(req, { data: { port, path, search: url.search, q: [] } })) {
405	          return undefined;
406	        }
407	        return new Response("upgrade failed", { status: 400 });
408	      }
409	
410	      const r = await fetch(`http://127.0.0.1:${port}${path}${url.search}`, {
411	        method: req.method,
412	        headers: upstreamHeaders(req.headers, `127.0.0.1:${port}`),
413	        body: req.body,
414	        redirect: "manual",
415	        // @ts-expect-error bun 需要 duplex 才能流式转发请求体
416	        duplex: "half",
417	      });
418	      return new Response(r.body, {
419	        status: r.status,
420	        headers: passthroughHeaders(r.headers),
421	      });
422	    }
423	
424	    if (!nextReady) return maintenancePage(authed(req));
425	
426	    try {
427	      const r = await fetch(`${NEXT_UP}${url.pathname}${url.search}`, {
428	        method: req.method,
429	        headers: upstreamHeaders(req.headers, `127.0.0.1:${NEXT_PORT}`),
430	        body: req.body,
431	        redirect: "manual",
432	        // @ts-expect-error bun 需要 duplex 才能流式转发请求体
433	        duplex: "half",
434	      });
435	      return new Response(r.body, {
436	        status: r.status,
437	        headers: passthroughHeaders(r.headers),
438	      });
439	    } catch {
440	      // Next 正好在这一刻死了（nextReady 还没翻）——别把裸 500 丢给用户。
441	      return maintenancePage(authed(req));
442	    }
443	  },
444	
445	  // 消息级 WS 转发（不是字节级）：ttyd 的协议就是普通的二进制/文本帧，
446	  // 逐帧转发即可。上游还没连上时先把客户端的帧排队，连上再补发 ——
447	  // ttyd 客户端一 open 就发 AuthToken，丢了它整条连接就废。
448	  websocket: {
449	    idleTimeout: 0,
450	    open(ws) {
451	      const d = ws.data;
452	      const up = new WebSocket(
453	        `ws://127.0.0.1:${d.port}${d.path}${d.search}`,
454	        ["tty"],
455	      );
456	      up.binaryType = "arraybuffer";
457	      d.up = up;
458	      up.onopen = () => {
459	        for (const m of d.q) up.send(m);
460	        d.q.length = 0;
461	      };
462	      up.onmessage = (e) =>
463	        ws.send(
464	          e.data instanceof ArrayBuffer ? new Uint8Array(e.data) : e.data,
465	        );
466	      up.onclose = () => ws.close();
467	      up.onerror = () => ws.close();
468	    },
469	    message(ws, msg) {
470	      const d = ws.data;
471	      if (d.up && d.up.readyState === 1) d.up.send(msg);
472	      else d.q.push(msg as string | Uint8Array);
473	    },
474	    close(ws) {
475	      try {
476	        ws.data.up?.close();
477	      } catch {
478	        /* 已经关了 */
479	      }
480	    },
481	  },
482	});
483	
484	console.log(
485	  `[trellis] gate listening on :${PORT}  (auth ${gateOn ? "ON" : "OFF"}, next→${NEXT_PORT})`,
486	);
487

