"use client";
import { useEffect, useState } from "react";

export type SelectionInfo = {
  text: string;
  rect: DOMRect;
  nodeId: string;
  // Snapshot of the selected Range, so the popover can paint its own
  // highlight (CSS Custom Highlight API) that survives the native selection
  // collapsing when the textarea is clicked. Cloned so later selectionchange
  // events don't mutate it. May be undefined in browsers without Range.
  range?: Range;
};

// Watches the document for text selections inside elements marked with
// data-chat-node-id. Returns the selection info, or null when nothing is
// selected (or selection is outside any chat node).
export function useSelectionWithin(): SelectionInfo | null {
  const [info, setInfo] = useState<SelectionInfo | null>(null);

  useEffect(() => {
    let timer: number | undefined;
    const compute = () => {
      const sel = window.getSelection();
      if (!sel || sel.isCollapsed || sel.rangeCount === 0) {
        setInfo(null);
        return;
      }
      const text = sel.toString().trim();
      if (!text) {
        setInfo(null);
        return;
      }
      const range = sel.getRangeAt(0);
      const container = range.commonAncestorContainer;
      const el =
        container.nodeType === Node.TEXT_NODE
          ? container.parentElement
          : (container as Element);
      const nodeEl = el?.closest("[data-chat-node-id]");
      if (!nodeEl) {
        setInfo(null);
        return;
      }
      const nodeId = nodeEl.getAttribute("data-chat-node-id");
      if (!nodeId) {
        setInfo(null);
        return;
      }
      const rect = range.getBoundingClientRect();
